const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isEnd = (c) => c === undefined || c === '#' || c === ';'

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }

  string() {
    const q = this.s[this.i++]
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      const cp = String.fromCodePoint(e.codePointAt(0))
      this.i += cp.length
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + cp)
    }
  }

  name() {
    this.ws()
    const c = this.peek()
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      this.ws()
      if (this.peek() !== '.') return names
      this.i++
      names.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.peek()
    if (isEnd(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
